// TASK_CHECK (task_support/check.h) is designed for the int-returning top
// level cases: on failure it prints and "return 1".  The bool-returning
// helpers below need to propagate "false" instead, so they use MODEL_CHECK.
// Every helper is itself invoked through a TASK_CHECK by a registered case.
#define MODEL_CHECK(x)                                                        \
  do {                                                                         \
    if (!(x)) {                                                                \
      fprintf(stderr, "MODEL_CHECK fail %s:%d: %s\n", __FILE__, __LINE__,     \
              #x);                                                             \
      return false;                                                            \
    }                                                                          \
  } while (0)

// ---------------------------------------------------------------------------
// Small generic helpers.
// ---------------------------------------------------------------------------

static std::vector<std::string> SplitLines(const std::string &Text) {
  std::vector<std::string> Lines;
  std::string Line;
  std::stringstream SS(Text);
  while (std::getline(SS, Line, '\n'))
    Lines.push_back(Line);
  return Lines;
}

static std::string JoinStrings(const std::vector<std::string> &V,
                               const char *Sep) {
  std::string R;
  for (size_t I = 0; I < V.size(); I++) {
    if (I) R += Sep;
    R += V[I];
  }
  return R;
}

template <class T>
static std::set<T> ToStdSet(const Vector<T> &V) {
  return std::set<T>(V.begin(), V.end());
}

template <class T>
static std::set<T> ToStdSet(const std::vector<T> &V) {
  return std::set<T>(V.begin(), V.end());
}

template <class T>
static std::set<T> ToStdSet(const std::set<T> &S) {
  return S;
}

// fuzzer::Set uses a custom allocator, so it is a distinct type from
// std::set; normalise through its iterators.
template <class T>
static std::set<T> ToStdSet(const Set<T> &V) {
  return std::set<T>(V.begin(), V.end());
}

template <class T>
static bool SameSet(const std::set<T> &A, const std::set<T> &B) {
  return A == B;
}

static bool SameSortedVector(const Vector<uint32_t> &A,
                             const std::vector<uint32_t> &B) {
  return A.size() == B.size() &&
         std::equal(A.begin(), A.end(), B.begin());
}

static std::string MakeTempDir(const char *Prefix) {
  const char *Base = getenv("TMPDIR");
  std::string Tmpl =
      std::string(Base && *Base ? Base : "/tmp") + "/" + Prefix + ".XXXXXX";
  std::vector<char> Buf(Tmpl.begin(), Tmpl.end());
  Buf.push_back('\0');
  char *Res = mkdtemp(Buf.data());
  if (!Res)
    return "";
  return std::string(Res);
}

static void WriteSmallFile(const std::string &Path, const std::string &Bytes) {
  WriteToFile(reinterpret_cast<const uint8_t *>(Bytes.data()), Bytes.size(),
              Path);
}

static std::vector<std::string> ListDirNames(const std::string &Dir) {
  std::vector<std::string> Out;
  DIR *D = opendir(Dir.c_str());
  if (!D)
    return Out; // Callers validate the expected entries themselves.
  struct dirent *E;
  while ((E = readdir(D))) {
    std::string Name = E->d_name;
    if (Name == "." || Name == "..")
      continue;
    Out.push_back(Name);
  }
  closedir(D);
  return Out;
}

static bool IsHexSha1Name(const std::string &Name) {
  if (Name.size() != 40)
    return false;
  for (char C : Name)
    if (!std::isxdigit(static_cast<unsigned char>(C)))
      return false;
  return true;
}

// Fixed-seed, bounded, local generator.  Its only job is to produce finite
// diverse byte strings; no standard-library random sequence is ever asserted.
struct BoundedRng {
  uint32_t State;
  explicit BoundedRng(uint32_t Seed) : State(Seed ? Seed : 1u) {}
  uint32_t Next() {
    // minstd-style LCG, independent of fuzzer::Random.
    State = State * 1664525u + 1013904223u;
    return State;
  }
  uint32_t Below(uint32_t N) { return N ? Next() % N : 0; }
};

// ---------------------------------------------------------------------------
// Independent reference model for a merge control log.
//
// This parser re-derives every fact from the raw log text, using only the
// documented grammar:
//   N
//   NumFilesInFirstCorpus
//   name*N
//   ( STARTED ID SIZE ( FT ID F... )? ( COV ID P... )* )*
// Only well-formed logs are generated, and they are only ever truncated on
// whole-line (complete record) boundaries.
// ---------------------------------------------------------------------------

struct RefFile {
  std::string Name;
  size_t Size = 0;
  bool Started = false;
  std::vector<uint32_t> FT;  // Sorted; duplicates retained, as in Merger.
  std::vector<uint32_t> COV; // First-seen order; globally unique.
};

struct RefJournal {
  size_t NumFiles = 0;
  size_t NumFilesInFirstCorpus = 0;
  size_t FirstNotProcessedFile = 0;
  std::string LastFailure;
  std::vector<RefFile> Files;
  std::map<uint32_t, size_t> CovOwner; // PC -> index of first owning file.
  bool Valid = false;
};

static RefJournal RefParseJournal(const std::string &Text) {
  RefJournal J;
  std::vector<std::string> Lines = SplitLines(Text);
  size_t LineIdx = 0;
  auto NeedLine = [&]() -> bool { return LineIdx < Lines.size(); };
  if (!NeedLine())
    return J;
  J.NumFiles = static_cast<size_t>(std::strtoul(Lines[LineIdx].c_str(), 0, 10));
  LineIdx++;
  if (!NeedLine() || J.NumFiles == 0 || J.NumFiles > 10000000)
    return J;
  J.NumFilesInFirstCorpus =
      static_cast<size_t>(std::strtoul(Lines[LineIdx].c_str(), 0, 10));
  LineIdx++;
  if (J.NumFilesInFirstCorpus > J.NumFiles)
    return J;
  J.Files.resize(J.NumFiles);
  for (size_t I = 0; I < J.NumFiles; I++) {
    if (!NeedLine())
      return J;
    J.Files[I].Name = Lines[LineIdx++];
  }
  size_t Expected = 0;
  bool HaveOpenStart = false;
  size_t OpenStart = 0;
  std::set<uint32_t> SeenPCs;
  for (; LineIdx < Lines.size(); LineIdx++) {
    std::stringstream ISS(Lines[LineIdx]);
    std::string Marker;
    size_t Id = 0;
    ISS >> Marker >> Id;
    if (Marker == "STARTED") {
      if (Id != Expected || !ISS)
        return J;
      size_t Size = 0;
      ISS >> Size;
      J.Files[Id].Size = Size;
      J.Files[Id].Started = true;
      HaveOpenStart = true;
      OpenStart = Id;
      Expected++;
    } else if (Marker == "FT") {
      if (!HaveOpenStart || Id != OpenStart)
        return J;
      uint32_t F = 0;
      while (ISS >> F)
        J.Files[Id].FT.push_back(F);
      std::sort(J.Files[Id].FT.begin(), J.Files[Id].FT.end());
      HaveOpenStart = false; // A STARTED must be closed before the next one.
    } else if (Marker == "COV") {
      // COV may repeat; PCs are globally de-duplicated, first occurrence wins.
      uint32_t P = 0;
      while (ISS >> P) {
        if (SeenPCs.insert(P).second) {
          J.Files[Id].COV.push_back(P);
          J.CovOwner[P] = Id;
        }
      }
    } else {
      return J;
    }
  }
  J.FirstNotProcessedFile = Expected;
  if (HaveOpenStart)
    J.LastFailure = J.Files[OpenStart].Name;
  J.Valid = true;
  return J;
}

// Independent greedy merge, mirroring the documented algorithm:
//   * seed AllFeatures with InitialFeatures + first-corpus features;
//   * strip already-known features from every candidate;
//   * order candidates by (size asc, remaining-feature-count desc) using a
//     STABLE sort so that exact ties keep one legal ordering;
//   * greedily accept any candidate that still adds a feature;
//   * collect every non-initial PC not in InitialCov regardless of selection.
struct RefMergeResult {
  std::set<uint32_t> NewFeatures;
  std::set<uint32_t> NewCov;
  std::vector<std::string> NewFiles;
  bool HasTie = false;
};

static RefMergeResult
RefMerge(const RefJournal &J, const std::set<uint32_t> &InitialFeatures,
         const std::set<uint32_t> &InitialCov) {
  RefMergeResult R;
  std::set<uint32_t> All = InitialFeatures;
  for (size_t I = 0; I < J.NumFilesInFirstCorpus; I++)
    All.insert(J.Files[I].FT.begin(), J.Files[I].FT.end());

  struct Cand {
    size_t Idx;
    size_t Size;
    std::vector<uint32_t> Residual;
  };
  std::vector<Cand> Cands;
  for (size_t I = J.NumFilesInFirstCorpus; I < J.NumFiles; I++) {
    Cand C;
    C.Idx = I;
    C.Size = J.Files[I].Size;
    std::set_difference(J.Files[I].FT.begin(), J.Files[I].FT.end(),
                        All.begin(), All.end(),
                        std::inserter(C.Residual, C.Residual.begin()));
    Cands.push_back(C);
  }
  std::stable_sort(Cands.begin(), Cands.end(),
                   [](const Cand &A, const Cand &B) {
                     if (A.Size != B.Size)
                       return A.Size < B.Size;
                     return A.Residual.size() > B.Residual.size();
                   });
  // After sorting, adjacent candidates with equal size and equal residual
  // weight are genuine comparator ties; either order is legal.
  for (size_t I = 1; I < Cands.size(); I++) {
    if (Cands[I].Size == Cands[I - 1].Size &&
        Cands[I].Residual.size() == Cands[I - 1].Residual.size())
      R.HasTie = true;
  }
  for (const Cand &C : Cands) {
    bool Added = false;
    for (uint32_t F : C.Residual) {
      if (All.insert(F).second) {
        Added = true;
        R.NewFeatures.insert(F);
      }
    }
    if (Added)
      R.NewFiles.push_back(J.Files[C.Idx].Name);
    for (uint32_t P : J.Files[C.Idx].COV)
      if (!InitialCov.count(P))
        R.NewCov.insert(P);
  }
  return R;
}

// Compare a freshly parsed production Merger against the reference parse.
// Coverage-on and coverage-off Mergers are checked separately by callers.
static bool MergerMatchesRef(const Merger &M, const RefJournal &J,
                             bool WithCoverage, const std::string &Ctx) {
  if (M.Files.size() != J.Files.size()) {
    fprintf(stderr, "%s: file count %zd != %zd\n", Ctx.c_str(), M.Files.size(),
            J.Files.size());
    return false;
  }
  if (M.NumFilesInFirstCorpus != J.NumFilesInFirstCorpus ||
      M.FirstNotProcessedFile != J.FirstNotProcessedFile ||
      M.LastFailure != J.LastFailure) {
    fprintf(stderr, "%s: progress mismatch (first=%zd/%zd fnpf=%zd/%zd "
            "failure='%s'/'%s')\n", Ctx.c_str(), M.NumFilesInFirstCorpus,
            J.NumFilesInFirstCorpus, M.FirstNotProcessedFile,
            J.FirstNotProcessedFile, M.LastFailure.c_str(),
            J.LastFailure.c_str());
    return false;
  }
  for (size_t I = 0; I < J.Files.size(); I++) {
    const MergeFileInfo &MF = M.Files[I];
    const RefFile &RF = J.Files[I];
    if (MF.Name != RF.Name || MF.Size != RF.Size) {
      fprintf(stderr, "%s: record %zd name/size mismatch\n", Ctx.c_str(), I);
      return false;
    }
    if (WithCoverage) {
      if (!SameSortedVector(MF.Features, RF.FT) ||
          !SameSortedVector(MF.Cov, RF.COV)) {
        fprintf(stderr, "%s: record %zd feature/PC projection mismatch\n",
                Ctx.c_str(), I);
        return false;
      }
    } else if (!MF.Features.empty() || !MF.Cov.empty()) {
      fprintf(stderr, "%s: record %zd collected coverage with parsing off\n",
              Ctx.c_str(), I);
      return false;
    }
  }
  return true;
}

// Run one full offline projection + merge comparison with fresh objects.
static bool CheckOfflineRound(const std::string &Log,
                              const std::set<uint32_t> &InitialFeatures,
                              const std::set<uint32_t> &InitialCov,
                              bool ExpectExactOrder,
                              const std::string &Ctx) {
  RefJournal J = RefParseJournal(Log);
  if (!J.Valid) {
    fprintf(stderr, "%s: reference parser rejected a log it generated\n",
            Ctx.c_str());
    return false;
  }
  Merger On;
  Merger Off;
  if (!On.Parse(Log, true) || !Off.Parse(Log, false)) {
    fprintf(stderr, "%s: Merger rejected a generated log\n", Ctx.c_str());
    return false;
  }
  if (!MergerMatchesRef(On, J, true, Ctx + ":cov-on"))
    return false;
  if (!MergerMatchesRef(Off, J, false, Ctx + ":cov-off"))
    return false;

  // Every PC is owned by exactly the file where it first appeared.
  for (const auto &KV : J.CovOwner) {
    size_t Owner = KV.second;
    const auto &Cov = J.Files[Owner].COV;
    if (std::find(Cov.begin(), Cov.end(), KV.first) == Cov.end()) {
      fprintf(stderr, "%s: PC %u ownership mismatch at record %zd\n",
              Ctx.c_str(), KV.first, Owner);
      return false;
    }
  }

  // Fresh Merger + empty output containers for the merge itself.
  Merger MergeM;
  if (!MergeM.Parse(Log, true))
    return false;
  Set<uint32_t> NewFeatures, NewCov;
  Vector<std::string> NewFiles;
  Set<uint32_t> InitF(InitialFeatures.begin(), InitialFeatures.end());
  Set<uint32_t> InitC(InitialCov.begin(), InitialCov.end());
  MergeM.Merge(InitF, &NewFeatures, InitC, &NewCov, &NewFiles);

  RefMergeResult Ref = RefMerge(J, InitialFeatures, InitialCov);
  if (!SameSet(ToStdSet(NewFeatures), Ref.NewFeatures) ||
      !SameSet(ToStdSet(NewCov), Ref.NewCov)) {
    fprintf(stderr, "%s: new feature/PC set mismatch\n", Ctx.c_str());
    return false;
  }
  if (ExpectExactOrder) {
    std::vector<std::string> Got(NewFiles.begin(), NewFiles.end());
    if (Got != Ref.NewFiles) {
      fprintf(stderr, "%s: exact tie-free order mismatch (%s) vs (%s)\n",
              Ctx.c_str(), JoinStrings(Got, ",").c_str(),
              JoinStrings(Ref.NewFiles, ",").c_str());
      return false;
    }
  } else if (!SameSet(ToStdSet(NewFiles), ToStdSet(Ref.NewFiles))) {
    fprintf(stderr, "%s: selected file set mismatch\n", Ctx.c_str());
    return false;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Log builder.  All generated logs are legal: marker ids are sequential, an
// FT always closes its STARTED (except the final dangling one), all feature
// and PC numbers are small in-range uint32 values.
// ---------------------------------------------------------------------------

struct BuildFile {
  std::string Name;
  size_t Size;
  std::vector<uint32_t> FT;
  std::vector<uint32_t> COV;
};

static std::string BuildLog(size_t NumFilesInFirstCorpus,
                            const std::vector<BuildFile> &Files,
                            bool DanglingLastStarted) {
  std::stringstream SS;
  SS << Files.size() << "\n" << NumFilesInFirstCorpus << "\n";
  for (const BuildFile &F : Files)
    SS << F.Name << "\n";
  for (size_t I = 0; I < Files.size(); I++) {
    SS << "STARTED " << I << " " << Files[I].Size << "\n";
    bool Last = I + 1 == Files.size();
    if (Last && DanglingLastStarted)
      break; // Recovery metadata left by a normally stopped task.
    SS << "FT " << I;
    for (uint32_t F : Files[I].FT)
      SS << " " << F;
    SS << "\n";
    if (!Files[I].COV.empty()) {
      SS << "COV " << I;
      for (uint32_t P : Files[I].COV)
        SS << " " << P;
      SS << "\n";
    }
  }
  return SS.str();
}

// ===========================================================================
// journal group: control-log projection, recovery progress and the two parse
// modes (coverage enabled vs disabled).
// ===========================================================================

static int Journal_BasicProjection(void) {
  std::vector<BuildFile> Files = {
      {"old-a", 5, {10, 11, 11}, {100, 101}},
      {"old-b", 6, {11, 12}, {101, 102}},          // PC 101 repeats.
      {"new-c", 3, {}, {103}},                     // Processed, zero new FT.
      {"new-d", 4, {12, 20, 20, 21}, {100, 104}},  // Duplicate FT numbers.
  };
  std::string Log = BuildLog(2, Files, false);
  RefJournal J = RefParseJournal(Log);
  TASK_CHECK(J.Valid);
  TASK_CHECK(J.FirstNotProcessedFile == 4);
  TASK_CHECK(J.LastFailure.empty());
  TASK_CHECK(J.CovOwner.at(101) == 0);
  TASK_CHECK(J.CovOwner.at(104) == 3);
  TASK_CHECK(J.Files[3].FT ==
             (std::vector<uint32_t>{12, 20, 20, 21})); // Sorted, dups kept.
  TASK_CHECK(J.Files[1].COV == (std::vector<uint32_t>{102})); // 101 deduped.

  Merger On, Off;
  TASK_CHECK(On.Parse(Log, true));
  TASK_CHECK(Off.Parse(Log, false));
  TASK_CHECK(MergerMatchesRef(On, J, true, "journal.basic.on"));
  TASK_CHECK(MergerMatchesRef(Off, J, false, "journal.basic.off"));
  // Coverage-off parse must not retain any projection data.
  for (const auto &F : Off.Files)
    TASK_CHECK(F.Features.empty() && F.Cov.empty());
  TASK_CHECK(On.Files[0].Size == 5 && On.Files[3].Size == 4);
  return 0;
}

static int Journal_RecordBoundaryTruncation(void) {
  std::vector<BuildFile> Files = {
      {"f0", 2, {1}, {7}}, {"f1", 4, {2, 3}, {8}},
      {"f2", 5, {3, 4}, {9}}, {"f3", 7, {5}, {}},
  };
  std::string Full = BuildLog(1, Files, false);
  std::vector<std::string> Lines = SplitLines(Full);
  // Header occupies 2 + N lines. Truncation keeps whole lines only.
  for (size_t Cut = 2 + Files.size(); Cut <= Lines.size(); Cut++) {
    std::string Prefix;
    for (size_t I = 0; I < Cut; I++)
      Prefix += Lines[I] + "\n";
    RefJournal J = RefParseJournal(Prefix);
    TASK_CHECK(J.Valid);
    Merger M;
    TASK_CHECK(M.Parse(Prefix, true));
    std::string Ctx = "journal.trunc.cut" + std::to_string(Cut);
    TASK_CHECK(MergerMatchesRef(M, J, true, Ctx));
    // Every file past the progress point must carry no projected features.
    for (size_t I = M.FirstNotProcessedFile; I < M.Files.size(); I++)
      TASK_CHECK(M.Files[I].Features.empty());
  }
  return 0;
}

static int Journal_DanglingLastStarted(void) {
  // The final STARTED has no FT: a task stopped normally, leaving recovery
  // metadata.  No process is terminated or crashed to produce this state.
  std::vector<BuildFile> Files = {
      {"a", 3, {10}, {20}},
      {"b", 4, {11}, {21}},
      {"c", 6, {12}, {22}},
  };
  std::string Log = BuildLog(1, Files, /*DanglingLastStarted=*/true);
  RefJournal J = RefParseJournal(Log);
  TASK_CHECK(J.Valid);
  TASK_CHECK(J.FirstNotProcessedFile == 3);
  TASK_CHECK(J.LastFailure == "c");
  TASK_CHECK(J.Files[2].Started && J.Files[2].FT.empty());
  TASK_CHECK(J.Files[0].FT == (std::vector<uint32_t>{10}));
  Merger On, Off;
  TASK_CHECK(On.Parse(Log, true));
  TASK_CHECK(Off.Parse(Log, false));
  TASK_CHECK(MergerMatchesRef(On, J, true, "journal.dangle.on"));
  TASK_CHECK(MergerMatchesRef(Off, J, false, "journal.dangle.off"));
  TASK_CHECK(On.LastFailure == "c" && On.FirstNotProcessedFile == 3);
  return 0;
}

static int Journal_ZeroFeatureAndCovOnly(void) {
  std::vector<BuildFile> Files = {
      {"a", 1, {1}, {50}},
      {"b", 2, {}, {51}},       // Empty FT line is a complete record.
      {"c", 2, {2}, {}},        // FT without any COV.
      {"d", 3, {}, {50, 52}},   // PC 50 already owned by file a.
  };
  std::string Log = BuildLog(1, Files, false);
  RefJournal J = RefParseJournal(Log);
  TASK_CHECK(J.Valid);
  TASK_CHECK(J.Files[1].FT.empty());
  TASK_CHECK(J.Files[2].COV.empty());
  TASK_CHECK(J.Files[3].COV == (std::vector<uint32_t>{52}));
  TASK_CHECK(J.CovOwner.at(50) == 0);
  Merger M;
  TASK_CHECK(M.Parse(Log, true));
  TASK_CHECK(MergerMatchesRef(M, J, true, "journal.zero"));
  return 0;
}

// ===========================================================================
// projection group: greedy merge semantics over small, exhaustively checked
// sets, including InitialFeatures/InitialCov, candidate lengths, old-corpus
// counts and tie handling.  Every merge uses a re-parsed Merger and empty
// output containers.
// ===========================================================================

static int Projection_AllInputsParticipate(void) {
  // Candidate length, old-corpus count, InitialFeatures and InitialCov all
  // influence the result; one candidate adds PCs but no features.
  std::vector<BuildFile> Files = {
      {"old0", 5, {10, 11}, {}},
      {"old1", 6, {11, 12}, {}},
      {"cand-small", 3, {20, 30}, {92, 93}},
      {"cand-mid", 4, {12, 20, 21}, {90, 92}},
      {"cand-cov", 4, {31}, {90, 91}},
      {"cand-pconly", 7, {}, {99}}, // Rejected, yet its PC is collected.
  };
  std::string Log = BuildLog(2, Files, false);
  std::set<uint32_t> InitF = {10};
  std::set<uint32_t> InitC = {90};
  TASK_CHECK(CheckOfflineRound(Log, InitF, InitC,
                               /*ExpectExactOrder=*/true,
                               "projection.all-inputs"));
  // Re-derive the concrete expectations independently.
  RefJournal J = RefParseJournal(Log);
  RefMergeResult R = RefMerge(J, InitF, InitC);
  TASK_CHECK(R.NewFeatures ==
             (std::set<uint32_t>{20, 21, 30, 31}));
  TASK_CHECK(R.NewCov == (std::set<uint32_t>{91, 92, 93, 99}));
  TASK_CHECK(R.NewFiles ==
             (std::vector<std::string>{"cand-small", "cand-mid",
                                       "cand-cov"}));
  // The PC-only candidate is not selected, but PC 99 is still reported.
  TASK_CHECK(std::find(R.NewFiles.begin(), R.NewFiles.end(),
                       "cand-pconly") == R.NewFiles.end());
  TASK_CHECK(R.NewCov.count(99) == 1);
  return 0;
}

static int Projection_ExactTieAnyLegalOrder(void) {
  // Same size, same residual weight: either candidate may win, but the
  // selected set and the covered feature set are fixed.
  std::vector<BuildFile> Files = {
      {"old0", 2, {1}, {}},
      {"tie-A", 3, {2, 3}, {}},
      {"tie-B", 3, {2, 3}, {}},
  };
  std::string Log = BuildLog(1, Files, false);
  TASK_CHECK(CheckOfflineRound(Log, {}, {}, /*ExpectExactOrder=*/false,
                               "projection.tie-identical"));
  RefJournal J = RefParseJournal(Log);
  RefMergeResult R = RefMerge(J, {}, {});
  TASK_CHECK(R.HasTie);
  TASK_CHECK(R.NewFeatures == (std::set<uint32_t>{2, 3}));
  TASK_CHECK(R.NewFiles.size() == 1);
  TASK_CHECK(R.NewFiles[0] == "tie-A" || R.NewFiles[0] == "tie-B");

  // Same size/count but disjoint features: order cannot change the fact that
  // both are selected.
  std::vector<BuildFile> Files2 = {
      {"old0", 2, {1}, {}},
      {"dis-A", 3, {2, 3}, {}},
      {"dis-B", 3, {4, 5}, {}},
  };
  std::string Log2 = BuildLog(1, Files2, false);
  TASK_CHECK(CheckOfflineRound(Log2, {}, {}, false, "projection.tie-disjoint"));
  RefJournal J2 = RefParseJournal(Log2);
  RefMergeResult R2 = RefMerge(J2, {}, {});
  TASK_CHECK(ToStdSet(R2.NewFiles) ==
             (std::set<std::string>{"dis-A", "dis-B"}));
  return 0;
}

static int Projection_TieFreeExactNames(void) {
  // Distinct sizes and distinct residual weights => a unique legal order.
  std::vector<BuildFile> Files = {
      {"old0", 10, {1}, {}},
      {"big", 9, {2, 3, 4}, {}},
      {"small", 2, {4, 5}, {}},
      {"mid", 5, {6}, {}},
  };
  std::string Log = BuildLog(1, Files, false);
  TASK_CHECK(CheckOfflineRound(Log, {}, {}, /*ExpectExactOrder=*/true,
                               "projection.exact"));
  RefJournal J = RefParseJournal(Log);
  RefMergeResult R = RefMerge(J, {}, {});
  TASK_CHECK(!R.HasTie);
  TASK_CHECK(R.NewFiles ==
             (std::vector<std::string>{"small", "mid", "big"}));
  TASK_CHECK(R.NewFeatures == (std::set<uint32_t>{2, 3, 4, 5, 6}));
  return 0;
}

static int Projection_InitialCovFiltering(void) {
  std::vector<BuildFile> Files = {
      {"old0", 1, {1}, {}},
      {"a", 2, {2}, {70, 71}},
      {"b", 3, {3}, {71, 72}},
      {"c", 4, {}, {73}},
  };
  std::string Log = BuildLog(1, Files, false);
  std::set<uint32_t> InitC = {70, 73};
  TASK_CHECK(CheckOfflineRound(Log, {}, InitC, false, "projection.cov"));
  RefJournal J = RefParseJournal(Log);
  RefMergeResult R = RefMerge(J, {}, InitC);
  // 70 and 73 were already known; 71 is reported once although two files
  // carry it; the rejected file c contributes nothing new.
  TASK_CHECK(R.NewCov == (std::set<uint32_t>{71, 72}));
  TASK_CHECK(R.NewFiles == (std::vector<std::string>{"a", "b"}));
  return 0;
}

static int Projection_FirstCorpusSeedsTheUnion(void) {
  // Everything the candidates offer is already in the first corpus (or in
  // InitialFeatures): the merge selects nothing.
  std::vector<BuildFile> Files = {
      {"old0", 8, {1, 2, 3}, {}},
      {"new0", 1, {1, 2}, {}},
      {"new1", 2, {3}, {}},
  };
  std::string Log = BuildLog(1, Files, false);
  TASK_CHECK(CheckOfflineRound(Log, {3}, {}, false, "projection.seeded"));
  RefJournal J = RefParseJournal(Log);
  RefMergeResult R = RefMerge(J, {3}, {});
  TASK_CHECK(R.NewFeatures.empty());
  TASK_CHECK(R.NewFiles.empty());
  return 0;
}

// Two fixed-seed generated traces with an explicit step cap.  Failure
// messages carry the seed, the step count and the smallest divergent record.
static bool RunGeneratedTrace(uint32_t Seed, size_t MaxSteps) {
  BoundedRng Rng(Seed);
  size_t Steps = 1 + Rng.Below(MaxSteps);
  size_t First = 1 + Rng.Below(Steps); // At least one old-corpus file.
  std::vector<BuildFile> Files;
  for (size_t Step = 0; Step < Steps; Step++) {
    BuildFile F;
    F.Name = "gen-" + std::to_string(Step);
    F.Size = 1 + Rng.Below(9);
    size_t NumFT = Rng.Below(5);
    for (size_t K = 0; K < NumFT; K++)
      F.FT.push_back(Rng.Below(40)); // Small, in-range assigned features.
    size_t NumCOV = Rng.Below(4);
    for (size_t K = 0; K < NumCOV; K++)
      F.COV.push_back(80 + Rng.Below(20)); // In-range assigned PC numbers.
    Files.push_back(F);
  }
  std::string Log = BuildLog(First, Files, false);
  std::set<uint32_t> InitF;
  for (size_t K = 0; K < Rng.Below(4); K++)
    InitF.insert(Rng.Below(40));
  std::set<uint32_t> InitC;
  for (size_t K = 0; K < Rng.Below(3); K++)
    InitC.insert(80 + Rng.Below(20));

  RefJournal J = RefParseJournal(Log);
  if (!J.Valid) {
    fprintf(stderr, "projection.gen seed=%u steps=%zd: bad reference parse\n",
            Seed, Steps);
    return false;
  }
  // Locate the smallest record where the production parse disagrees.
  Merger M;
  if (!M.Parse(Log, true)) {
    fprintf(stderr, "projection.gen seed=%u steps=%zd: Merger rejected log\n",
            Seed, Steps);
    return false;
  }
  for (size_t I = 0; I < J.Files.size(); I++) {
    if (!SameSortedVector(M.Files[I].Features, J.Files[I].FT) ||
        !SameSortedVector(M.Files[I].Cov, J.Files[I].COV) ||
        M.Files[I].Size != J.Files[I].Size) {
      fprintf(stderr,
              "projection.gen seed=%u steps=%zd smallest-bad-record=%zd\n",
              Seed, Steps, I);
      return false;
    }
  }
  std::string Ctx = "projection.gen seed=" + std::to_string(Seed) +
                    " steps=" + std::to_string(Steps);
  return CheckOfflineRound(Log, InitF, InitC, /*ExpectExactOrder=*/false, Ctx);
}

static int Projection_GeneratedTraceOne(void) {
  TASK_CHECK(RunGeneratedTrace(/*Seed=*/11477, /*MaxSteps=*/10));
  return 0;
}

static int Projection_GeneratedTraceTwo(void) {
  TASK_CHECK(RunGeneratedTrace(/*Seed=*/90210, /*MaxSteps=*/12));
  return 0;
}

// ---------------------------------------------------------------------------
// Online ownership model.  A real InputCorpus is driven in the exact order
// used by Fuzzer::RunOne: AddFeature for every observed feature first, then a
// single AddToCorpus when at least one feature was accepted.  An independent
// map tracks the current smallest-size owner of every feature slot.
// ---------------------------------------------------------------------------

static const size_t kModelFeatureSetSize = 1u << 21; // Mirrors InputCorpus.

struct OnlineState {
  // InputCorpus embeds two 2^21-entry arrays (~16 MiB); keep it off the
  // stack, exactly as the production driver does (new InputCorpus).
  InputCorpus *Corpus;
  // Feature slot -> (corpus index, size).
  std::map<uint32_t, std::pair<size_t, uint32_t>> Owner;
  size_t Updates = 0;
  bool Shrink;
  explicit OnlineState(bool Shrink_)
      : Corpus(new InputCorpus("")), Shrink(Shrink_) {}
  ~OnlineState() { delete Corpus; }
};

struct Candidate {
  Unit Bytes;
  std::vector<uint32_t> Features;
};

static Unit MakeUnit(size_t Size, uint8_t Tag) {
  Unit U(Size);
  for (size_t I = 0; I < Size; I++)
    U[I] = static_cast<uint8_t>(Tag + I);
  return U;
}

// Replay one candidate through the production corpus and the reference map,
// asserting agreement after every step.
static bool ReplayCandidate(OnlineState &S, const Candidate &C,
                            const std::string &Ctx) {
  MODEL_CHECK(!C.Bytes.empty());
  uint32_t NewSize = static_cast<uint32_t>(C.Bytes.size());
  std::set<uint32_t> RefAcceptedSlots;
  for (uint32_t F : C.Features) {
    uint32_t Slot = F % kModelFeatureSetSize;
    auto It = S.Owner.find(Slot);
    bool RefTake = false;
    if (It == S.Owner.end())
      RefTake = true; // Brand-new slot.
    else if (S.Shrink && It->second.second > NewSize)
      RefTake = true; // Strictly smaller owner only.
    bool ProdTake = S.Corpus->AddFeature(F, NewSize, S.Shrink);
    if (ProdTake != RefTake) {
      fprintf(stderr, "%s: AddFeature disagreement feature=%u slot=%u\n",
              Ctx.c_str(), F, Slot);
      return false;
    }
    if (RefTake) {
      RefAcceptedSlots.insert(Slot);
      S.Owner[Slot] = std::make_pair(S.Corpus->size(), NewSize);
      S.Updates++;
    }
  }
  if (!RefAcceptedSlots.empty()) {
    static DataFlowTrace DFT; // Empty trace; BaseII is null.
    Vector<uint32_t> Feat(RefAcceptedSlots.begin(), RefAcceptedSlots.end());
    InputInfo *II = S.Corpus->AddToCorpus(
        C.Bytes, RefAcceptedSlots.size(), /*MayDeleteFile=*/false,
        /*HasFocusFunction=*/false, Feat, DFT, /*BaseII=*/nullptr);
    if (!II)
      return false;
  }

  // Global counters: distinct slots ever created, and total updates.
  if (S.Corpus->NumFeatures() != S.Owner.size()) {
    fprintf(stderr, "%s: NumFeatures %zd != owners %zd\n", Ctx.c_str(),
            S.Corpus->NumFeatures(), S.Owner.size());
    return false;
  }
  if (S.Corpus->NumFeatureUpdates() != S.Updates) {
    fprintf(stderr, "%s: NumFeatureUpdates %zd != %zd\n", Ctx.c_str(),
            S.Corpus->NumFeatureUpdates(), S.Updates);
    return false;
  }
  // Per-input ownership counts and active bytes, through the public surface.
  std::map<size_t, size_t> RefNF;
  for (const auto &KV : S.Owner)
    RefNF[KV.second.first]++;
  size_t RefActive = 0, RefBytes = 0;
  for (size_t I = 0; I < S.Corpus->size(); I++) {
    const Unit &U = (*S.Corpus)[I];
    size_t Want = RefNF.count(I) ? RefNF[I] : 0;
    if (!U.empty()) {
      RefActive++;
      RefBytes += U.size();
    }
    if (Want == 0)
      MODEL_CHECK(U.empty()); // Lost its last feature => emptied.
  }
  if (S.Corpus->NumActiveUnits() != RefActive ||
      S.Corpus->SizeInBytes() != RefBytes) {
    fprintf(stderr,
            "%s: active %zd/%zd bytes %zd/%zd\n", Ctx.c_str(),
            S.Corpus->NumActiveUnits(), RefActive, S.Corpus->SizeInBytes(),
            RefBytes);
    return false;
  }
  return true;
}

// Same replay, but retaining the InputInfo pointers so NumFeatures on the
// production objects can be checked field-by-field.
struct OnlineTracked {
  InputCorpus *Corpus;
  std::map<uint32_t, std::pair<InputInfo *, uint32_t>> Owner;
  std::vector<InputInfo *> Order;
  size_t Updates = 0;
  bool Shrink;
  explicit OnlineTracked(bool Shrink_)
      : Corpus(new InputCorpus("")), Shrink(Shrink_) {}
  ~OnlineTracked() { delete Corpus; }
};

static bool ReplayTracked(OnlineTracked &S, const Candidate &C,
                          const std::string &Ctx) {
  uint32_t NewSize = static_cast<uint32_t>(C.Bytes.size());
  std::set<uint32_t> Accepted;
  for (uint32_t F : C.Features) {
    uint32_t Slot = F % kModelFeatureSetSize;
    auto It = S.Owner.find(Slot);
    bool Take = (It == S.Owner.end()) ||
                (S.Shrink && It->second.second > NewSize);
    MODEL_CHECK(S.Corpus->AddFeature(F, NewSize, S.Shrink) == Take);
    if (Take)
      Accepted.insert(Slot);
  }
  InputInfo *II = nullptr;
  if (!Accepted.empty()) {
    static DataFlowTrace DFT;
    Vector<uint32_t> Feat(Accepted.begin(), Accepted.end());
    II = S.Corpus->AddToCorpus(C.Bytes, Accepted.size(), false, false, Feat,
                              DFT, nullptr);
    MODEL_CHECK(II != nullptr);
    S.Order.push_back(II);
    for (uint32_t Slot : Accepted)
      S.Owner[Slot] = std::make_pair(II, NewSize);
    S.Updates += Accepted.size();
  }
  // Verify every production InputInfo's NumFeatures against the ref map.
  std::map<InputInfo *, size_t> RefNF;
  for (const auto &KV : S.Owner)
    RefNF[KV.second.first]++;
  for (InputInfo *P : S.Order) {
    size_t Want = RefNF.count(P) ? RefNF[P] : 0;
    if (P->NumFeatures != Want) {
      fprintf(stderr, "%s: InputInfo.NumFeatures %zd != %zd\n", Ctx.c_str(),
              P->NumFeatures, Want);
      return false;
    }
    if (Want == 0)
      MODEL_CHECK(P->U.empty());
  }
  MODEL_CHECK(S.Corpus->NumFeatureUpdates() == S.Updates);
  MODEL_CHECK(S.Corpus->NumFeatures() == S.Owner.size());
  return true;
}

static int Ownership_ShrinkOnTakeover(void) {
  OnlineTracked S(/*Shrink=*/true);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(4, 1), {10, 11}}, "shrink-on.1"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(2, 2), {11, 12}}, "shrink-on.2"));
  TASK_CHECK(S.Corpus->NumFeatures() == 3); // Slots 10, 11, 12.
  TASK_CHECK(S.Corpus->NumFeatureUpdates() == 4);
  TASK_CHECK(S.Order[0]->NumFeatures == 1); // Lost slot 11, keeps 10.
  TASK_CHECK(S.Order[1]->NumFeatures == 2); // Owns 11 and 12.
  TASK_CHECK(S.Corpus->NumActiveUnits() == 2);
  TASK_CHECK(S.Corpus->SizeInBytes() == 6);
  return 0;
}

static int Ownership_EqualSizeNeverTakesOver(void) {
  // Shrink disabled: no takeover happens at all.
  OnlineTracked Off(/*Shrink=*/false);
  TASK_CHECK(ReplayTracked(Off, {MakeUnit(3, 1), {20}}, "equal.off.1"));
  TASK_CHECK(ReplayTracked(Off, {MakeUnit(3, 2), {20, 21}}, "equal.off.2"));
  TASK_CHECK(Off.Owner.at(20).first == Off.Order[0]);
  TASK_CHECK(Off.Order[0]->NumFeatures == 1);
  TASK_CHECK(Off.Order[1]->NumFeatures == 1); // Only slot 21 accepted.

  // Shrink enabled, but equal size still loses (strictly smaller required).
  OnlineTracked On(/*Shrink=*/true);
  TASK_CHECK(ReplayTracked(On, {MakeUnit(3, 3), {20}}, "equal.on.1"));
  TASK_CHECK(ReplayTracked(On, {MakeUnit(3, 4), {20, 21}}, "equal.on.2"));
  TASK_CHECK(On.Owner.at(20).first == On.Order[0]);
  TASK_CHECK(On.Order[0]->NumFeatures == 1);
  TASK_CHECK(On.Order[1]->NumFeatures == 1);
  return 0;
}

static int Ownership_DifferentNumbersSameSlot(void) {
  OnlineTracked S(/*Shrink=*/true);
  uint32_t A = 5;
  uint32_t B = 5 + static_cast<uint32_t>(kModelFeatureSetSize);
  TASK_CHECK(A % kModelFeatureSetSize == B % kModelFeatureSetSize);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(5, 1), {A}}, "slot.1"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(2, 2), {B}}, "slot.2"));
  TASK_CHECK(S.Corpus->NumFeatures() == 1); // One slot, two numbers.
  TASK_CHECK(S.Corpus->NumFeatureUpdates() == 2);
  TASK_CHECK(S.Order[0]->U.empty());       // Evicted.
  TASK_CHECK(S.Order[1]->NumFeatures == 1);
  TASK_CHECK(S.Corpus->NumActiveUnits() == 1);
  return 0;
}

static int Ownership_LastFeatureEvicts(void) {
  OnlineTracked S(/*Shrink=*/true);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(5, 1), {30}}, "evict.1"));
  TASK_CHECK(S.Corpus->NumActiveUnits() == 1);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(2, 2), {30}}, "evict.2"));
  TASK_CHECK(S.Order[0]->NumFeatures == 0);
  TASK_CHECK(S.Order[0]->U.empty()); // Last feature gone => cleared.
  TASK_CHECK(S.Corpus->NumActiveUnits() == 1);
  TASK_CHECK(S.Corpus->SizeInBytes() == 2);
  TASK_CHECK(S.Corpus->NumFeatures() == 1); // Slot still exists.
  TASK_CHECK(S.Corpus->NumFeatureUpdates() == 2);
  return 0;
}

static int Ownership_OneCandidateTakesOverMany(void) {
  OnlineTracked S(/*Shrink=*/true);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(5, 1), {40}}, "multi.1"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(6, 2), {41}}, "multi.2"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(1, 3), {40, 41, 42}}, "multi.3"));
  TASK_CHECK(S.Order[0]->U.empty());
  TASK_CHECK(S.Order[1]->U.empty());
  TASK_CHECK(S.Order[2]->NumFeatures == 3);
  TASK_CHECK(S.Corpus->NumActiveUnits() == 1);
  TASK_CHECK(S.Corpus->SizeInBytes() == 1);
  TASK_CHECK(S.Corpus->NumFeatures() == 3);
  TASK_CHECK(S.Corpus->NumFeatureUpdates() == 5);
  return 0;
}

static int Ownership_ReplaceIdentity(void) {
  OnlineTracked S(/*Shrink=*/true);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(6, 10), {50, 51}}, "replace.1"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(3, 20), {52}}, "replace.2"));
  InputInfo *II = S.Order[0];
  std::string OldSha = Sha1ToString(II->Sha1);
  Unit OldBytes = II->U;
  Unit NewBytes = MakeUnit(2, 30);
  std::string NewSha = Hash(NewBytes);
  TASK_CHECK(OldSha != NewSha);
  size_t ActiveBefore = S.Corpus->NumActiveUnits();
  S.Corpus->Replace(II, NewBytes);
  TASK_CHECK(II->Reduced);
  TASK_CHECK(Sha1ToString(II->Sha1) == NewSha);
  TASK_CHECK(Sha1ToString(II->Sha1) != OldSha);
  TASK_CHECK(II->U == NewBytes);
  TASK_CHECK(!(II->U == OldBytes));
  TASK_CHECK(S.Corpus->NumActiveUnits() == ActiveBefore);
  TASK_CHECK(S.Corpus->SizeInBytes() == 5); // 2 + 3.
  TASK_CHECK(II->NumFeatures == 2);        // Ownership untouched by Replace.
  return 0;
}

static int Ownership_FixedSeedSampling(void) {
  // Build a corpus where several inputs stay active and a few are evicted.
  OnlineTracked S(/*Shrink=*/true);
  TASK_CHECK(ReplayTracked(S, {MakeUnit(8, 1), {60}}, "sample.1"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(8, 2), {61}}, "sample.2"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(8, 3), {62}}, "sample.3"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(2, 4), {60, 63}}, "sample.4"));
  TASK_CHECK(ReplayTracked(S, {MakeUnit(3, 5), {61, 64}}, "sample.5"));
  std::set<size_t> ActiveIdx;
  for (size_t I = 0; I < S.Corpus->size(); I++)
    if (!(*S.Corpus)[I].empty())
      ActiveIdx.insert(I);
  TASK_CHECK(ActiveIdx.size() >= 2);
  TASK_CHECK(S.Corpus->NumActiveUnits() == ActiveIdx.size());

  // Fixed seed, bounded number of draws.  Assert ownership/non-emptiness only,
  // never a particular library sampling sequence or a probability threshold.
  Random Rand(/*seed=*/12345);
  const size_t kDraws = 4000;
  std::set<size_t> Hit;
  for (size_t I = 0; I < kDraws; I++) {
    size_t Idx = S.Corpus->ChooseUnitIdxToMutate(Rand);
    TASK_CHECK(Idx < S.Corpus->size());
    TASK_CHECK(!(*S.Corpus)[Idx].empty());
    Hit.insert(Idx);
  }
  // Every still-owned, non-empty input must be reachable.
  TASK_CHECK(Hit == ActiveIdx);
  return 0;
}

// ===========================================================================
// End-to-end checks against the real .task-build/merge-fixture binary.  The
// fixture is a benign, always-successful coverage target; only finite merge
// runs are performed, never random mutation.
// ===========================================================================

static std::string FixturePath(void) {
  const char *Env = getenv("MERGE_FIXTURE_PATH");
  if (Env && *Env && IsFile(Env))
    return Env;
  if (IsFile(".task-build/merge-fixture"))
    return ".task-build/merge-fixture";
  return "";
}

static int RunFixtureCommand(const std::string &Bin, const std::string &CF,
                             const std::string &Old,
                             const std::vector<std::string> &NewDirs) {
  std::string Cmd = "'" + Bin + "' -merge=1 -merge_control_file='" + CF +
                    "' '" + Old + "'";
  for (const auto &D : NewDirs)
    Cmd += " '" + D + "'";
  int Status = std::system(Cmd.c_str());
  return WIFEXITED(Status) ? WEXITSTATUS(Status) : -1;
}

// Feed a real control log plus the actual on-disk bytes through both models.
static bool CrossCheckRealRun(const std::string &CF,
                              const std::string &Root,
                              const std::string &OldDir,
                              const std::string &Ctx) {
  std::string Log = FileToString(CF);
  RefJournal J = RefParseJournal(Log);
  if (!J.Valid || J.FirstNotProcessedFile != J.NumFiles) {
    fprintf(stderr, "%s: real log incomplete or unparseable\n", Ctx.c_str());
    return false;
  }
  Merger M;
  if (!M.Parse(Log, true) || !MergerMatchesRef(M, J, true, Ctx + ".parse"))
    return false;

  // Record sizes must equal the actual byte counts.
  for (size_t I = 0; I < J.Files.size(); I++) {
    size_t OnDisk = FileSize(J.Files[I].Name);
    if (OnDisk != J.Files[I].Size || OnDisk != M.Files[I].Size) {
      fprintf(stderr, "%s: record %zd size disagrees with disk\n", Ctx.c_str(),
              I);
      return false;
    }
  }

  // Offline model: fresh parse, empty output containers.
  Merger MergeM;
  MODEL_CHECK(MergeM.Parse(Log, true));
  Set<uint32_t> NewFeatures, NewCov;
  Vector<std::string> NewFiles;
  MergeM.Merge({}, &NewFeatures, {}, &NewCov, &NewFiles);
  RefMergeResult Ref = RefMerge(J, {}, {});
  if (!SameSet(ToStdSet(NewFeatures), Ref.NewFeatures) ||
      !SameSet(ToStdSet(NewCov), Ref.NewCov) ||
      !SameSet(ToStdSet(NewFiles), ToStdSet(Ref.NewFiles))) {
    fprintf(stderr, "%s: offline model mismatch on real log\n", Ctx.c_str());
    return false;
  }

  // Online model: replay records in control-log order, RunOne semantics
  // (AddFeature over the record's FT, then one AddToCorpus on any update).
  // The FT lists are incremental new-feature records, not full coverage; the
  // ownership replay still follows the same AddFeature/AddToCorpus ordering.
  OnlineState On(/*Shrink=*/false);
  for (size_t I = 0; I < J.Files.size(); I++) {
    Candidate C;
    C.Bytes = FileToVector(J.Files[I].Name);
    MODEL_CHECK(!C.Bytes.empty());
    C.Features = J.Files[I].FT;
    if (!ReplayCandidate(On, C, Ctx + ".online." + std::to_string(I)))
      return false;
  }

  // Every selected source file must have been copied into OldDir under its
  // SHA1 name with byte-identical content.
  std::map<std::string, std::string> ShaToBytes;
  for (size_t I = 0; I < J.Files.size(); I++) {
    Unit U = FileToVector(J.Files[I].Name);
    ShaToBytes[Hash(U)] = std::string(U.begin(), U.end());
  }
  std::vector<std::string> OutNames = ListDirNames(OldDir);
  std::set<std::string> OutputShas;
  for (const std::string &Name : OutNames) {
    if (!IsHexSha1Name(Name))
      continue; // Original seed inputs keep their own names.
    OutputShas.insert(Name);
    std::string Path = OldDir + "/" + Name;
    Unit Disk = FileToVector(Path);
    auto It = ShaToBytes.find(Name);
    if (It == ShaToBytes.end() ||
        std::string(Disk.begin(), Disk.end()) != It->second) {
      fprintf(stderr, "%s: output '%s' is not a SHA-named copy of any input\n",
              Ctx.c_str(), Name.c_str());
      return false;
    }
  }
  // Every selected input must correspond to one SHA-named output.
  for (const std::string &Selected : Ref.NewFiles) {
    Unit U = FileToVector(Selected);
    if (!OutputShas.count(Hash(U))) {
      fprintf(stderr, "%s: selected %s has no SHA output\n", Ctx.c_str(),
              Selected.c_str());
      return false;
    }
  }
  (void)Root;
  return true;
}

static bool FixtureScenario(const std::vector<std::string> &OldInputs,
                            const std::vector<std::string> &NewInputs,
                            const std::string &Ctx) {
  std::string Bin = FixturePath();
  if (Bin.empty()) {
    fprintf(stderr, "%s: .task-build/merge-fixture missing\n", Ctx.c_str());
    return false;
  }
  std::string Root = MakeTempDir("corpus-model-e2e");
  MODEL_CHECK(!Root.empty());
  std::string OldDir = Root + "/old";
  std::string NewDir = Root + "/new";
  MkDir(OldDir);
  MkDir(NewDir);
  for (size_t I = 0; I < OldInputs.size(); I++)
    WriteSmallFile(OldDir + "/seed-" + std::to_string(I), OldInputs[I]);
  for (size_t I = 0; I < NewInputs.size(); I++)
    WriteSmallFile(NewDir + "/cand-" + std::to_string(I), NewInputs[I]);
  std::string CF = Root + "/control.txt";

  MODEL_CHECK(RunFixtureCommand(Bin, CF, OldDir, {NewDir}) == 0);
  MODEL_CHECK(FileSize(CF) > 0);
  MODEL_CHECK(CrossCheckRealRun(CF, Root, OldDir, Ctx));

  // Restore the original input-file set: drop the SHA-named merge outputs.
  for (const std::string &Name : ListDirNames(OldDir))
    if (IsHexSha1Name(Name))
      RemoveFile(OldDir + "/" + Name);
  std::string FirstLog = FileToString(CF);

  // A completed log for the same file set must short-circuit: exit success,
  // no records appended (the control file is byte-identical, no recopying).
  MODEL_CHECK(RunFixtureCommand(Bin, CF, OldDir, {NewDir}) == 0);
  std::string SecondLog = FileToString(CF);
  if (FirstLog != SecondLog) {
    fprintf(stderr, "%s: completed merge appended/rewrote records\n",
            Ctx.c_str());
    return false;
  }
  for (const std::string &Name : ListDirNames(OldDir))
    MODEL_CHECK(!IsHexSha1Name(Name)); // Nothing recopied on the fast path.
  RmDirRecursive(Root);
  return true;
}

static int Projection_FixtureMixedCorpus(void) {
  TASK_CHECK(FixtureScenario(/*OldInputs=*/{"A"},
                             /*NewInputs=*/{"AB", "ABC", "ZZZ"},
                             "e2e.mixed"));
  return 0;
}

static int Projection_FixtureEmptyOldCorpus(void) {
  // Includes a zero-coverage candidate ("ZZZ") that must be rejected.
  TASK_CHECK(FixtureScenario(/*OldInputs=*/{},
                             /*NewInputs=*/{"A", "AB", "ABC", "ZZZ", "Q"},
                             "e2e.empty-old"));
  return 0;
}

